import assert from 'node:assert/strict';

import { writeAppManifest } from './helpers/app-fixture';
import { readAppStateFiles } from './helpers/app-state-files';
import { runDomindsCli } from './helpers/cli-process';
import { semanticEvidenceCollector } from './helpers/semantic-evidence';
import { withTempRtws } from './kernel-driver/helpers';

const evidence = semanticEvidenceCollector('dominds-app-cli-guidance-');
async function main(): Promise<void> {
  await withTempRtws(async (rtws) => {
    await writeAppManifest(rtws, 'rtws_root');
    const before = await readAppStateFiles(rtws);
    const help = runDomindsCli(['help'], rtws);
    assert.equal(help.status, 0);
    assert.deepEqual(await readAppStateFiles(rtws), before);
    evidence.record({
      id: 'help',
      scenario: 'A user reads main CLI help to find the compatibility-package diagnosis command.',
      businessValue:
        'Discover read-only diagnosis and its appropriate use before changing package state.',
      context: { invokedCommand: 'dominds help', exitStatus: 0, appStateFilesUnchanged: true },
      reviewQuestions: [
        'Does the actual help explain how to invoke doctor and the state layers it diagnoses?',
        'Is its example usable without implying diagnosis mutates those layers or that the old App design remains the destination?',
      ],
      actualText: help.stdout + '\nSTDERR:\n' + help.stderr,
    });
    const id = '@longrun-ai/missing-app';
    const update = runDomindsCli(['update', id], rtws);
    assert.equal(update.status, 1);
    assert.deepEqual(await readAppStateFiles(rtws), before);
    evidence.record({
      id: 'unknown-update',
      scenario: 'A user attempts update for a package not declared in the root manifest.',
      businessValue:
        'Explain the refused update and a concrete diagnosis step while preserving package state.',
      context: {
        appId: id,
        invokedCommand: `dominds update ${id}`,
        exitStatus: 1,
        appStateFilesUnchanged: true,
      },
      reviewQuestions: [
        'Does the actual error explain the undeclared target and give an applicable doctor command?',
        'Does the guidance encourage diagnosis without falsely claiming a completed update?',
      ],
      actualText: update.stdout + '\nSTDERR:\n' + update.stderr,
    });
  });
  await evidence.write();
  console.log(
    'help succeeds and undeclared update fails without changing App state; guidance is separate subjective evidence: passed',
  );
}
main().catch((error: unknown) => {
  console.error(error);
  process.exitCode = 1;
});

import assert from 'node:assert/strict';
import path from 'node:path';

import { writeAppsResolutionFile } from '../main/apps/resolution-file';
import { runDoctor } from '../main/cli/doctor';
import { resolvedApp, writeAppManifest, writeAppText, writeLocalApp } from './helpers/app-fixture';
import { readAppStateFiles } from './helpers/app-state-files';
import { runDomindsCli } from './helpers/cli-process';
import { semanticEvidenceCollector } from './helpers/semantic-evidence';
import { withTempRtws } from './kernel-driver/helpers';

const evidence = semanticEvidenceCollector('dominds-app-doctor-handshake-');
async function main(): Promise<void> {
  await withTempRtws(async (rtws) => {
    const id = '@longrun-ai/doctor-case';
    const supplied = await writeLocalApp(
      path.join(rtws, 'dominds-apps', '@longrun-ai', 'doctor-case'),
      id,
    );
    await writeAppManifest(rtws, 'rtws_root', [id]);
    await writeAppText(
      path.join(rtws, '.minds', 'app-lock.yaml'),
      JSON.stringify({ schemaVersion: 1, apps: [{ id, package: { name: id, version: '0.0.0' } }] }),
    );
    await writeAppText(
      path.join(rtws, '.apps', 'configuration.yaml'),
      'schemaVersion: 1\nresolutionStrategy:\n  order: [local]\n',
    );
    for (const [variant, moduleChanged, exportChanged] of [
      ['module', true, false],
      ['export', false, true],
      ['both', true, true],
      ['healthy', false, false],
    ] as const) {
      const entry = resolvedApp({
        ...supplied,
        host: {
          ...supplied.host,
          moduleRelPath: moduleChanged ? 'src/app-host.js' : supplied.host.moduleRelPath,
          exportName: exportChanged ? 'createDomindsAppHost' : supplied.host.exportName,
        },
      });
      await writeAppsResolutionFile({
        rtwsRootAbs: rtws,
        file: { schemaVersion: 1, apps: [entry] },
      });
      const before = await readAppStateFiles(rtws);
      const report = await runDoctor({ rtwsRootAbs: rtws, appId: id });
      assert.equal(report.diagnoses.length, 1);
      const diagnosis = report.diagnoses[0];
      assert.equal(diagnosis.appId, id);
      assert.equal(diagnosis.status, variant === 'healthy' ? 'healthy' : 'degraded');
      assert.equal(diagnosis.declared, true);
      assert.equal(diagnosis.disabled, false);
      assert.deepEqual(diagnosis.resolutionEntry, entry);
      assert.deepEqual(diagnosis.freshProbe, {
        appId: id,
        source: entry.source,
        hostModuleRelPath: supplied.host.moduleRelPath,
        hostExportName: supplied.host.exportName,
        packageName: id,
        packageVersion: '0.0.0',
      });
      assert.deepEqual(report.freshResolutionById.get(id)?.installJson, supplied);
      assert.deepEqual(report.issues, []);
      if (variant === 'healthy') assert.deepEqual(diagnosis.reasons, []);
      assert.deepEqual(await readAppStateFiles(rtws), before);
      const cli = runDomindsCli(['doctor', id], rtws);
      // doctor reports diagnosis; the current public CLI returns0 for completed degraded reports too.
      assert.equal(cli.status, 0);
      assert.deepEqual(await readAppStateFiles(rtws), before);
      evidence.record({
        id: variant,
        scenario: `Fresh local app JSON is compared against a cached entry with ${variant === 'healthy' ? 'matching host module and export' : variant + ' host mismatch'}.`,
        businessValue:
          'Diagnose stale host metadata before edits without silently rewriting state or confusing app JSON with a running host.',
        context: {
          appId: id,
          moduleMismatch: moduleChanged,
          exportMismatch: exportChanged,
          status: diagnosis.status,
          appStateFilesUnchanged: true,
          hostFactoryStarted: false,
        },
        reviewQuestions: [
          'Do actual reasons identify every changed host field and distinguish cached values from fresh package data?',
          'Are next actions usable and consistent with read-only diagnosis, without claiming a host was started or silently fixed?',
          'For the healthy control, does the actual guidance avoid inventing a mismatch?',
        ],
        actualText: JSON.stringify({ diagnosis, stdout: cli.stdout, stderr: cli.stderr }, null, 2),
      });
    }
  });
  await evidence.write();
  console.log(
    'doctor compares each fresh host field, reports degraded or healthy state and preserves every App state file: passed',
  );
}
main().catch((error: unknown) => {
  console.error(error);
  process.exitCode = 1;
});

import assert from 'node:assert/strict';

import { runDoctor } from '../main/cli/doctor';
import { writeAppManifest } from './helpers/app-fixture';
import { readAppStateFiles } from './helpers/app-state-files';
import { runDomindsCli } from './helpers/cli-process';
import { semanticEvidenceCollector } from './helpers/semantic-evidence';
import { withTempRtws } from './kernel-driver/helpers';

const evidence = semanticEvidenceCollector('dominds-app-doctor-self-');
async function main(): Promise<void> {
  await withTempRtws(async (rtws) => {
    await writeAppManifest(rtws, 'chatgpt-workstation');
    const before = await readAppStateFiles(rtws);
    const report = await runDoctor({ rtwsRootAbs: rtws, appId: '.' });
    assert.equal(report.diagnoses.length, 1);
    const diagnosis = report.diagnoses[0];
    assert.equal(diagnosis.appId, '.');
    assert.equal(diagnosis.declared, true);
    assert.equal(diagnosis.status, 'healthy');
    assert.deepEqual(diagnosis.reasons, []);
    assert.deepEqual(report.issues, []);
    assert.equal(diagnosis.resolutionEntry, null);
    assert.equal(diagnosis.freshProbe, null);
    assert.deepEqual(await readAppStateFiles(rtws), before);
    const cli = runDomindsCli(['doctor', '.'], rtws);
    assert.equal(cli.status, 0);
    assert.deepEqual(await readAppStateFiles(rtws), before);
    evidence.record({
      id: 'self-no-dependencies',
      scenario:
        'The root workspace manifest exists and intentionally declares no package dependencies; the user runs doctor .',
      businessValue:
        'A dependency-free root is a valid healthy workspace and diagnosis must remain read-only.',
      context: {
        rootManifestId: 'chatgpt-workstation',
        target: '.',
        declared: true,
        status: diagnosis.status,
        packageSnapshotAbsent: true,
        appStateFilesUnchanged: true,
      },
      reviewQuestions: [
        'Do the actual CLI output and API next actions correctly distinguish a healthy root manifest from missing dependency package data?',
        'Could the user understand that the unresolved package-handshake fields do not require installing the root as its own dependency?',
      ],
      actualText: JSON.stringify({ diagnosis, stdout: cli.stdout, stderr: cli.stderr }, null, 2),
    });
  });
  await evidence.write();
  console.log(
    'doctor self-target accepts an intentional dependency-free root and preserves all App state files: passed',
  );
}
main().catch((error: unknown) => {
  console.error(error);
  process.exitCode = 1;
});

import assert from 'node:assert/strict';
import * as fs from 'node:fs/promises';
import path from 'node:path';

import { loadAppLockFile } from '../main/apps/app-lock-file';
import { loadAppsConfigurationFile } from '../main/apps/configuration-file';
import { loadDomindsAppManifest } from '../main/apps/manifest';
import { Team } from '../main/team';
import {
  readAppResolution,
  writeAppManifest,
  writeAppText,
  writeLocalApp,
} from './helpers/app-fixture';
import { readAppStateFiles } from './helpers/app-state-files';
import { runDomindsCli } from './helpers/cli-process';
import { semanticEvidenceCollector } from './helpers/semantic-evidence';
import { withTempRtws, writeStandardMinds } from './kernel-driver/helpers';

const evidence = semanticEvidenceCollector('dominds-app-install-members-');
async function main(): Promise<void> {
  await withTempRtws(async (rtws) => {
    await writeStandardMinds(rtws);
    await writeAppManifest(rtws, 'rtws_root');
    const id = '@tests/install-flow-package';
    const root = path.join(rtws, 'dominds-apps', '@tests', 'install-flow-package');
    const base = await writeLocalApp(root, id, {
      defaultPort: 0,
      teammatesYamlRelPath: '.minds/team.yaml',
    });
    const supplied = { ...base, package: { ...base.package, version: '0.1.0' } };
    await writeAppText(path.join(root, 'app-json.json'), JSON.stringify(supplied));
    await writeAppText(
      path.join(root, 'package.json'),
      JSON.stringify({ name: id, version: '0.1.0', bin: 'bin.js' }),
    );
    const members = {
      reviewer: {
        name: 'Reviewer From Component',
        toolsets: ['ws_read'],
        gofor: ['verify imported component behavior'],
      },
      implementer: {
        name: 'Implementer From Component',
        toolsets: ['ws_read', 'ws_mod', 'codex_inspect_and_patch_tools'],
        gofor: ['implement changes using the selected component capabilities'],
      },
    };
    await writeAppText(path.join(root, '.minds', 'team.yaml'), JSON.stringify({ members }));
    const cli = runDomindsCli(['install', id, '--enable'], rtws);
    assert.equal(cli.status, 0);
    const manifest = await loadDomindsAppManifest({
      packageRootAbs: rtws,
      manifestRelPath: '.minds/app.yaml',
    });
    assert.equal(manifest.kind, 'ok');
    assert.equal(manifest.manifest.dependencies?.length, 1);
    assert.equal(manifest.manifest.dependencies?.[0].id, id);
    const configuration = await loadAppsConfigurationFile({ rtwsRootAbs: rtws });
    assert.notEqual(configuration.kind, 'error');
    if (configuration.kind === 'error') throw new Error(configuration.errorText);
    assert.deepEqual(configuration.file.disabledApps ?? [], []);
    const lock = await loadAppLockFile({ rtwsRootAbs: rtws });
    assert.notEqual(lock.kind, 'error');
    if (lock.kind === 'error') throw new Error(lock.errorText);
    assert.deepEqual(lock.file.apps, [{ id, package: { name: id, version: '0.1.0' } }]);
    const resolution = await readAppResolution(rtws);
    assert.equal(resolution.apps.length, 1);
    const entry = resolution.apps[0];
    assert.equal(entry.id, id);
    assert.equal(entry.enabled, true);
    assert.equal(entry.source.kind, 'local');
    assert.equal(
      entry.source.kind === 'local' ? await fs.realpath(entry.source.pathAbs) : null,
      await fs.realpath(root),
    );
    assert.deepEqual(entry.installJson, supplied);
    assert.ok(typeof entry.assignedPort === 'number' && entry.assignedPort > 0);
    await writeAppText(
      path.join(rtws, '.minds', 'team.yaml'),
      JSON.stringify({
        member_defaults: { provider: 'local-mock', model: 'default' },
        default_responder: 'builder',
        members: {
          builder: { name: 'Builder', toolsets: [] },
          reviewer_from_package: { from: id, use: 'reviewer', name: 'Reviewer Override' },
          implementer_from_package: { from: id, use: 'implementer', name: 'Implementer Override' },
        },
      }),
    );
    const before = await readAppStateFiles(rtws);
    const team = await Team.load();
    const actual: unknown[] = [];
    for (const [key, source, name] of [
      ['reviewer_from_package', members.reviewer, 'Reviewer Override'],
      ['implementer_from_package', members.implementer, 'Implementer Override'],
    ] as const) {
      const member = team.getMember(key);
      assert.ok(member);
      assert.equal(member.name, name);
      assert.deepEqual(member.toolsets, source.toolsets);
      assert.deepEqual(member.gofor, source.gofor);
      actual.push({
        id: member.id,
        name: member.name,
        toolsets: member.toolsets,
        gofor: member.gofor,
      });
    }
    assert.deepEqual(await readAppStateFiles(rtws), before);
    evidence.record({
      id: 'install-local-members',
      scenario:
        'A scoped package ID resolves locally, is installed/enabled, and contributes two member templates; root configuration overrides names while retaining supplied toolsets and purposes.',
      businessValue:
