        },
      },
    ]);

    const resolutionLoaded = await loadAppsResolutionFile({ rtwsRootAbs: tmpRoot });
    if (resolutionLoaded.kind !== 'ok') throw new Error(resolutionLoaded.errorText);
    assert.equal(resolutionLoaded.kind, 'ok', 'expected ok');
